KG42.register("clusters-6c6a160439a0c6f8476a81bb",{"id":"37-dsm_auction_incentives::v142-d-CL003","paper":"37-dsm_auction_incentives","label":"Configuration-related billing and historical cheating transfer payments","record":{"cluster_id":"v142-d-CL003","label":"Configuration-related billing and historical cheating transfer payments","market_meaning":"The distribution company uses declaration information and the selected consumption configuration to determine user payment obligations, and uses historical declaration and actual consumption information to form enhanced transfer payments for subsequent periods. The normal and enhanced implementations are retained separately, and the zero-sum requirement applies only to the transfer-payment component.","mechanism_ids":["v141-a-M01"],"market_types":["DEM"],"process_stages":["bidding","coordination","clearing","settlement"],"scope_disposition":"conditional","scope_explanation":"R006 primarily contains billing, the normal transfer base term, the enhanced adjustment and historical penalty content. The Method 2 declaration interface, the fixed-daily-total configuration branch, utility comparison for the same unit of energy, and the zero-sum transfer component each retain their original conditions; gaps remain in the Method 1 scope, penalty implementation and historical-use timing.","assembly_status":"partial","boundary_rationale":"Declaration, configuration and historical records are respectively information sources for billing and enhanced transfer payments, with identifiable amount outputs and subsequent penalty obligations. The shared chain supplies only these input interfaces and does not count declaration, configuration or record custody as additional charging rules.","chain_bindings":[{"chain_id":"v141-c-R006","ownership":"primary","role":"core","rationale":"Uniformly carries the payment rule, normal and enhanced transfer payments, historical penalties, and the zero-sum requirement for the transfer component."},{"chain_id":"v141-c-R001","ownership":"shared","role":"interface","rationale":"Provides the conditional entry point for the Method 2 declaration tuple and utility-parameter computation, retaining the different information structure of Method 1."},{"chain_id":"v141-c-R002","ownership":"shared","role":"interface","rationale":"Provides the configuration result used in payment evaluation and the fixed-daily-total reduction condition."},{"chain_id":"v141-c-R003","ownership":"shared","role":"support","rationale":"Supplies the distribution company's responsibility to keep historical declaration and actual electricity-use information, providing a record source for historical billing."}],"connections":[{"connection_id":"v142-d-CL003-C01","from_chain_id":"v141-c-R001","to_chain_id":"v141-c-R006","kind":"quantity_interface","from_refs":["v141-c-R001::x::v141-c-R001-X006","v141-c-R001::phi::v141-c-R001-C006","v141-c-R001::phi::v141-c-R001-C007"],"to_refs":["v141-c-R006::theta::v141-c-R006-PAR-theta_hat","v141-c-R006::phi::v141-c-R006-C001","v141-c-R006::phi::v141-c-R006-C007"],"evidence_ids":["v141-b-g02-e005","v141-b-g02-e008","v141-b-g02-e011"],"rationale":"The per-user declaration content of Method 2 enters the aggregated information used for payment; utility parameters are computed according to the consumption plan. This interface does not equate per-user tuples with the overall configuration, nor does it merge utility parameters directly declared under Method 1 into the Method 2 tuple."},{"connection_id":"v142-d-CL003-C02","from_chain_id":"v141-c-R002","to_chain_id":"v141-c-R006","kind":"quantity_interface","from_refs":["v141-c-R002::x::v141-c-R002-X001","v141-c-R002::phi::v141-c-R002-C001","v141-c-R002::phi::v141-c-R002-C004"],"to_refs":["v141-c-R006::x::v141-c-R006-VAR-x_i_s","v141-c-R006::phi::v141-c-R006-C003","v141-c-R006::phi::v141-c-R006-C007"],"evidence_ids":["v141-b-g01-e08","v141-b-g02-e006","v141-b-g02-e007","v141-b-g02-e008"],"rationale":"Payment evaluation uses the corresponding hourly components of the configuration vector, and the source directly gives the functional connection between configuration and payment. The vector, the hourly components and the ex post true daily total remain objects with different roles."},{"connection_id":"v142-d-CL003-C03","from_chain_id":"v141-c-R003","to_chain_id":"v141-c-R006","kind":"functional_coupling","from_refs":["v141-c-R003::phi::v141-c-R003-C002"],"to_refs":["v141-c-R006::x::v141-c-R006-VAR-x_i_total","v141-c-R006::theta::v141-c-R006-PAR-x_hat_i","v141-c-R006::phi::v141-c-R006-C004","v141-c-R006::phi::v141-c-R006-C009"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e06","v141-b-g02-e011","v141-b-g02-e013","v141-b-g02-e014","v141-b-g02-e022"],"rationale":"The declaration and consumption records that the distribution company keeps and receives connect with the source's statement that subsequent transfer payments are increased based on past true consumption. Here only the functional interface from records to historical billing is identified, and it is not assumed that an expectation estimate or record-update algorithm has already been provided."}],"object_mappings":[{"mapping_id":"v142-d-CL003-M01","kind":"same_node","member_refs":["v141-c-R001::V::bidding.demand","v141-c-R002::V::bidding.demand","v141-c-R003::V::bidding.demand","v141-c-R006::V::bidding.demand"],"canonical_ref":"v141-c-R001::V::bidding.demand","display_policy":"single_representative","evidence_ids":["v141-b-g01-e06","v141-b-g02-e005","v141-b-g02-e006","v141-b-g02-e008","v141-b-g02-e011"],"rationale":"The four places reference the same demand-submission node and are respectively located in the declaration, configuration, receipt and billing functions. The unified presentation does not eliminate the scope of each function, nor does it merge their quantity objects."},{"mapping_id":"v142-d-CL003-M02","kind":"same_node","member_refs":["v141-c-R002::V::clearing.social_welfare","v141-c-R006::V::clearing.social_welfare"],"canonical_ref":"v141-c-R002::V::clearing.social_welfare","display_policy":"single_representative","evidence_ids":["v141-b-g02-e006","v141-b-g02-e007","v141-b-g02-e008"],"rationale":"The configuration chain and the payment chain reference the same configuration node; the object representation is used only to locate the configuration source and does not collapse the objective conditions or payment constraints."}],"gaps":[{"gap_id":"v142-d-CL003-G01","category":"upstream_missing","description":"B currently has candidate transcriptions of (21) and (22), but frozen C retains only the corresponding function objects and does not have complete constraints expressing the counterfactual configuration and the normal transfer payment. The relevant expectation distribution and denominator applicability conditions are also not closed in C.","chain_ids":["v141-c-R006"],"object_refs":["v141-c-R006::theta::v141-c-R006-PAR-h_i","v141-c-R006::x::v141-c-R006-VAR-ts_i_norm","v141-c-R006::theta::v141-c-R006-PAR-N","v141-c-R006::phi::v141-c-R006-C007","v141-c-R006::phi::v141-c-R006-C009"],"evidence_ids":["v141-b-g02-e009","v141-b-g02-e010"],"proposal_ids":[],"required_work":"Upstream is to check and formalize the existing (21) and (22) materials, clarifying the configuration problem after excluding a user, the distribution on which the expectation is based, and the validity conditions for the number of users; D does not directly add formula objects from B."},{"gap_id":"v142-d-CL003-G02","category":"math_incomplete","description":"The candidate transcription of (24) contains ambiguity in the self-exclusion summation index and the repeated expectation term, so C retains only the ct_i function. Its weight r_2 has also not entered the frozen parameter catalogue, and the enhanced transfer payment and zero-sum requirement cannot yet be fully rechecked.","chain_ids":["v141-c-R006"],"object_refs":["v141-c-R006::theta::v141-c-R006-PAR-ct_i","v141-c-R006::phi::v141-c-R006-C006","v141-c-R006::phi::v141-c-R006-C009"],"evidence_ids":["v141-b-g02-e010","v141-b-g02-e013","v141-b-g02-e014","v141-b-g02-e017"],"proposal_ids":[],"required_work":"Check the index, expectation, weight and zero-sum derivation of (24) and their symbolic correspondence with (22)-(24), and then have C supplement the penalty definition and parameters. The zero-sum recheck is limited to the transfer component and is not generalized to a balance of all electricity charges or supply costs."},{"gap_id":"v142-d-CL003-G03","category":"scope_conflict","description":"R006-C001 and the declaration-parameter object explicitly adopt Method 2, whereas the payment-form expression in C007 is more general. The sources of utility information in Method 1 and Method 2 differ; the candidate citation also reports that underreporting utility parameters under Method 1 may yield a benefit, which cannot be assembled into an unconditional truthfulness conclusion.","chain_ids":["v141-c-R001","v141-c-R006"],"object_refs":["v141-c-R001::x::v141-c-R001-X005","v141-c-R001::x::v141-c-R001-X006","v141-c-R001::theta::v141-c-R001-T001","v141-c-R006::theta::v141-c-R006-PAR-theta_hat","v141-c-R006::phi::v141-c-R006-C001","v141-c-R006::phi::v141-c-R006-C007"],"evidence_ids":["v141-b-g02-e004","v141-b-g02-e005","v141-b-g02-e008","v141-b-g03-e04","v141-b-g03-e05"],"proposal_ids":[],"required_work":"Upstream is to clarify the input interpretation of the payment form under the two methods and the applicable conditions of the truthfulness claim; retain the different tuples, and check their interfaces after supplementing the Method 2 computation scheme."},{"gap_id":"v142-d-CL003-G04","category":"ambiguous_mapping","description":"The income/expenditure direction and value domain of t_i, and the reference relationship between the general ts_i and the normal and enhanced implementations, have not yet been unified; the textual direction in C007 also needs to be checked against the convention of benefit minus payment. The hat notation of the parameters in each transfer term also needs to be retained for verification.","chain_ids":["v141-c-R006"],"object_refs":["v141-c-R006::x::v141-c-R006-VAR-t_i","v141-c-R006::x::v141-c-R006-VAR-ts_i","v141-c-R006::x::v141-c-R006-VAR-ts_i_norm","v141-c-R006::x::v141-c-R006-VAR-ts_i_enhanced","v141-c-R006::phi::v141-c-R006-C006","v141-c-R006::phi::v141-c-R006-C007","v141-c-R006::phi::v141-c-R006-C009"],"evidence_ids":["v141-b-g01-e11","v141-b-g01-e26","v141-b-g02-e008","v141-b-g02-e010","v141-b-g02-e013","v141-b-g02-e017"],"proposal_ids":[],"required_work":"Check the payment direction, numerical domain and the choice of transfer implementation in each expression, and clarify the role of the normal term as the base term of the enhanced term. The three transfer objects remain separately accessible, and similar symbols are not taken to mean that the functions are equal or duplicates of one another."},{"gap_id":"v142-d-CL003-G05","category":"math_incomplete","description":"The direction of deviation in the English gloss of C008 needs to be checked: the frozen piecewise expression targets the aggregate deviation in which other users' actual consumption exceeds their declarations, and deviations of opposite sign may offset each other; it is not the per-person deviation of user i themselves. The existing content cannot directly imply the additional penalty for each user with a cheating record described in C004.","chain_ids":["v141-c-R006"],"object_refs":["v141-c-R006::x::v141-c-R006-VAR-x_i_total","v141-c-R006::theta::v141-c-R006-PAR-x_hat_i","v141-c-R006::theta::v141-c-R006-PAR-ct_i","v141-c-R006::phi::v141-c-R006-C004","v141-c-R006::phi::v141-c-R006-C008","v141-c-R006::phi::v141-c-R006-C009"],"evidence_ids":["v141-b-g01-e03","v141-b-g02-e013","v141-b-g02-e014","v141-b-g02-e015","v141-b-g02-e018"],"proposal_ids":[],"required_work":"Check the deviation direction, the index for excluding users, and the aggregation method; explain how the historical expectation and redistribution generate an individual penalty; and clarify the relevant behavior, weights and tolerance conditions; retain the current C text and mathematical content for manual checking."},{"gap_id":"v142-d-CL003-G06","category":"upstream_missing","description":"Payment is set before consumption, and the true daily total is learned after consumption. The source supports the influence of historical records on subsequent periods but does not fully explain the historical window, expectation estimation, record updating, or which period the penalty is counted in.","chain_ids":["v141-c-R003","v141-c-R006"],"object_refs":["v141-c-R003::phi::v141-c-R003-C002","v141-c-R006::x::v141-c-R006-VAR-x_i_total","v141-c-R006::phi::v141-c-R006-C004","v141-c-R006::phi::v141-c-R006-C007","v141-c-R006::phi::v141-c-R006-C009"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e06","v141-b-g02-e011","v141-b-g02-e012","v141-b-g02-e014","v141-b-g02-e022"],"proposal_ids":[],"required_work":"B/C are to clarify the time points at which records become available, the statistical updating and the cross-period billing relationship; before that, only the historical-data interface is retained, and the current period's ex post actual consumption is not treated as an ex ante known input for that period."},{"gap_id":"v142-d-CL003-G07","category":"ontology_extension","description":"AGV transfers, the zero-sum transfer component, historical penalties and truthfulness verification are currently concentrated near the generic payment node; the related proposals remain pending. Billing content and the zero-sum statement cannot replace independent checks of incentive compatibility or individual rationality conditions.","chain_ids":["v141-c-R006"],"object_refs":["v141-c-R006::V::settlement.payment","v141-c-R006::phi::v141-c-R006-C004","v141-c-R006::phi::v141-c-R006-C006","v141-c-R006::phi::v141-c-R006-C009"],"evidence_ids":["v141-b-g01-e01","v141-b-g01-e03","v141-b-g01-e14","v141-b-g01-e16","v141-b-g01-e17","v141-b-g02-e012","v141-b-g02-e018","v141-b-g02-e019","v141-b-g03-e06","v141-b-g03-e07","v141-b-g03-e10","v141-b-g03-e11"],"proposal_ids":["v141-b-g01-p02","v141-b-g01-p03","v141-b-g01-p04","proposal:v141-b-g02-p001","v141-b-g03-p01"],"required_work":"Manually process the listed ontology proposals, and have upstream separately record the applicable conditions and evidence for the mechanism properties; this round provides only citation assembly and does not activate proposals or deem the properties established."},{"gap_id":"v142-d-CL003-G08","category":"unverified_source","description":"All B citations for billing, historical penalties and property discussions remain unverified; experimental candidate status does not mean that formula transcription or scientific argumentation is correct.","chain_ids":["v141-c-R001","v141-c-R002","v141-c-R003","v141-c-R006"],"object_refs":["v141-c-R003::phi::v141-c-R003-C002","v141-c-R006::phi::v141-c-R006-C006","v141-c-R006::phi::v141-c-R006-C007","v141-c-R006::phi::v141-c-R006-C008","v141-c-R006::phi::v141-c-R006-C009"],"evidence_ids":["v141-b-g01-e01","v141-b-g01-e03","v141-b-g01-e06","v141-b-g01-e08","v141-b-g01-e11","v141-b-g01-e14","v141-b-g01-e16","v141-b-g01-e17","v141-b-g01-e26","v141-b-g02-e004","v141-b-g02-e005","v141-b-g02-e006","v141-b-g02-e007","v141-b-g02-e008","v141-b-g02-e009","v141-b-g02-e010","v141-b-g02-e011","v141-b-g02-e012","v141-b-g02-e013","v141-b-g02-e014","v141-b-g02-e015","v141-b-g02-e017","v141-b-g02-e018","v141-b-g02-e019","v141-b-g02-e022","v141-b-g03-e04","v141-b-g03-e05","v141-b-g03-e06","v141-b-g03-e07","v141-b-g03-e10","v141-b-g03-e11"],"proposal_ids":[],"required_work":"According to the experimental arrangement, manual work is to check the original pages, formulas and scope chain by chain; retain all frozen objects and the current source status, and do not claim that B audit or C2 independent review has been completed."}]},"rule_refs":["37-dsm_auction_incentives::v141-c-R006","37-dsm_auction_incentives::v141-c-R001","37-dsm_auction_incentives::v141-c-R002","37-dsm_auction_incentives::v141-c-R003"],"unresolved_rule_refs":[],"node_ids":["COMP-20a5cdf8b3b1e9c9","COMP-ebacec241379c91d","KG40-14a3066c15f25075","KG40-3482a1190712c456"]});
